/**
 * The browser add-on's files (browser-addon/), embedded so "Save the add-on" works from an installed plugin.
 * Generated by scripts/embed-addon.mjs; do not edit by hand (tests/live-capture.test.ts compares it with the folder).
 */
export const ADDON_FILES: Readonly<Record<string, string>> = {
  "manifest.json": "{\n  \"manifest_version\": 3,\n  \"name\": \"Cortex live capture\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Sends each finished chat turn on the sites you approve to Cortex on this computer. Nothing goes anywhere else.\",\n  \"minimum_chrome_version\": \"111\",\n  \"permissions\": [\"storage\", \"scripting\", \"alarms\"],\n  \"host_permissions\": [\"http://127.0.0.1/*\"],\n  \"optional_host_permissions\": [\"https://chatgpt.com/*\", \"https://chat.openai.com/*\", \"https://claude.ai/*\", \"https://gemini.google.com/*\"],\n  \"background\": { \"service_worker\": \"background.js\" },\n  \"options_ui\": { \"page\": \"options.html\", \"open_in_tab\": true },\n  \"action\": { \"default_title\": \"Cortex live capture\", \"default_popup\": \"options.html\" }\n}\n",
  "core.js": "/*\n * Cortex live capture: the part that needs no page. Which sites, which conversation, which turns are finished.\n * Loaded before content.js on the sites you approve, and by the tests (which feed it made-up snapshots).\n */\n(function (root) {\n  \"use strict\";\n\n  /* The only sites this add-on can ever read. You approve each one on the options page and can remove it again. */\n  var SITES = {\n    chatgpt: { label: \"ChatGPT\", hosts: [\"chatgpt.com\", \"chat.openai.com\"], matches: [\"https://chatgpt.com/*\", \"https://chat.openai.com/*\"], conversation: /\\/c\\/([A-Za-z0-9-]{8,})/ },\n    claude: { label: \"Claude\", hosts: [\"claude.ai\"], matches: [\"https://claude.ai/*\"], conversation: /\\/chat\\/([A-Za-z0-9-]{8,})/ },\n    gemini: { label: \"Gemini\", hosts: [\"gemini.google.com\"], matches: [\"https://gemini.google.com/*\"], conversation: /\\/app\\/([A-Za-z0-9_-]{8,})/ }\n  };\n\n  function siteOfHost(host) {\n    var h = String(host || \"\").toLowerCase();\n    for (var id in SITES) if (SITES[id].hosts.indexOf(h) >= 0) return id;\n    return null;\n  }\n\n  /* The site's own conversation id from the address path; null on a page that is not a conversation yet. */\n  function conversationOf(site, pathname) {\n    var s = SITES[site];\n    if (!s) return null;\n    var m = s.conversation.exec(String(pathname || \"\"));\n    return m ? m[1] : null;\n  }\n\n  /* cyrb53: a short stable fingerprint of a string (not a secret, only an id). */\n  function hash53(str) {\n    var h1 = 0xdeadbeef, h2 = 0x41c6ce57;\n    for (var i = 0; i < str.length; i++) {\n      var ch = str.charCodeAt(i);\n      h1 = Math.imul(h1 ^ ch, 2654435761);\n      h2 = Math.imul(h2 ^ ch, 1597334677);\n    }\n    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);\n    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);\n    return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);\n  }\n\n  /*\n   * Ids for turns that carry none in the page: role and text, plus a counter for exact repeats, so a turn keeps its id\n   * when older messages load above it. `turns` is [{ role, text, id? }] in page order; a given id is kept.\n   */\n  function withIds(conversation, turns) {\n    var counts = {};\n    return turns.map(function (t) {\n      var text = String(t.text || \"\").trim();\n      if (t.id) return { id: String(t.id), role: t.role, text: text };\n      var key = t.role + \"|\" + hash53(text);\n      var n = counts[key] || 0;\n      counts[key] = n + 1;\n      return { id: conversation + \":\" + hash53(key) + (n ? \".\" + n : \"\"), role: t.role, text: text };\n    });\n  }\n\n  /*\n   * Decides which turns are finished. A turn counts when its text has not changed for `settleMs` and the page is not\n   * still writing a reply. Turns already on the page when it opened (the first `baselineMs`) are not sent unless\n   * `backfill` is on, so opening an old conversation does not copy it.\n   */\n  function createTracker(opts) {\n    opts = opts || {};\n    var settleMs = opts.settleMs == null ? 3000 : opts.settleMs;\n    var baselineMs = opts.baselineMs == null ? 4000 : opts.baselineMs;\n    var backfill = !!opts.backfill;\n    var startedAt = null;\n    var seen = Object.create(null);\n    var done = Object.create(null);\n    return {\n      update: function (now, turns, busy) {\n        if (startedAt === null) startedAt = now;\n        var out = [];\n        var present = Object.create(null);\n        for (var i = 0; i < turns.length; i++) {\n          var t = turns[i];\n          if (!t.text) continue;\n          present[t.id] = true;\n          var s = seen[t.id];\n          if (!s) s = seen[t.id] = { text: t.text, changedAt: now };\n          else if (s.text !== t.text) { s.text = t.text; s.changedAt = now; }\n          if (done[t.id]) continue;\n          if (!backfill && now - startedAt < baselineMs) { done[t.id] = \"baseline\"; continue; }\n          if (busy && t.role === \"assistant\") continue;\n          if (now - s.changedAt < settleMs) continue;\n          done[t.id] = \"sent\";\n          out.push({ id: t.id, role: t.role, text: s.text, at: new Date(now).toISOString() });\n        }\n        for (var id in seen) if (!present[id] && !done[id]) delete seen[id];\n        return out;\n      },\n      /* True while something is waiting to settle (the page keeps polling then). */\n      pending: function () {\n        for (var id in seen) if (!done[id]) return true;\n        return false;\n      }\n    };\n  }\n\n  /* The page title without the site's own name; null when nothing else is left. */\n  function cleanTitle(title) {\n    var t = String(title || \"\").replace(/\\s+/g, \" \").trim().replace(/\\s*[-|–—]\\s*(ChatGPT|Claude|Gemini|Google Gemini)\\s*$/i, \"\").trim();\n    return t === \"\" || /^(ChatGPT|Claude|Gemini|Google Gemini)$/i.test(t) ? null : t.slice(0, 200);\n  }\n\n  var api = { SITES: SITES, siteOfHost: siteOfHost, conversationOf: conversationOf, hash53: hash53, withIds: withIds, createTracker: createTracker, cleanTitle: cleanTitle };\n  if (typeof module !== \"undefined\" && module.exports) module.exports = api;\n  else root.CortexCaptureCore = api;\n})(typeof globalThis !== \"undefined\" ? globalThis : this);\n",
  "content.js": "/*\n * Cortex live capture: the page side. Runs only on the sites you approved on the options page. It reads the visible\n * conversation, waits until a turn is finished (core.js), and hands it to the background script, which posts it to\n * Cortex on 127.0.0.1. It never reads anything but the chat messages, and never changes the page.\n *\n * The selectors below are the one place that knows how each site draws its messages. Sites change their markup now\n * and then: if a site stops being captured, this table is what needs updating.\n */\n(function () {\n  \"use strict\";\n  var core = globalThis.CortexCaptureCore;\n  if (!core || typeof chrome === \"undefined\" || !chrome.runtime) return;\n  var site = core.siteOfHost(location.hostname);\n  if (!site) return;\n\n  function textOf(el) {\n    return (el.innerText || el.textContent || \"\").trim();\n  }\n\n  var SELECTORS = {\n    chatgpt: {\n      turns: function (doc) {\n        var out = [];\n        doc.querySelectorAll(\"[data-message-author-role]\").forEach(function (el) {\n          var role = el.getAttribute(\"data-message-author-role\");\n          if (role !== \"user\" && role !== \"assistant\") return;\n          out.push({ id: el.getAttribute(\"data-message-id\") || undefined, role: role, text: textOf(el) });\n        });\n        return out;\n      },\n      busy: function (doc) {\n        return !!doc.querySelector('[data-testid=\"stop-button\"], button[aria-label*=\"Stop\"]');\n      }\n    },\n    claude: {\n      turns: function (doc) {\n        var out = [];\n        var any = '[data-testid=\"user-message\"], .font-claude-response, .font-claude-message';\n        doc.querySelectorAll(any).forEach(function (el) {\n          if (el.parentElement && el.parentElement.closest(any)) return;\n          out.push({ role: el.matches('[data-testid=\"user-message\"]') ? \"user\" : \"assistant\", text: textOf(el) });\n        });\n        return out;\n      },\n      busy: function (doc) {\n        return !!doc.querySelector('[data-is-streaming=\"true\"], button[aria-label*=\"Stop\"]');\n      }\n    },\n    gemini: {\n      turns: function (doc) {\n        var out = [];\n        doc.querySelectorAll(\"user-query, model-response\").forEach(function (el) {\n          var user = el.tagName.toLowerCase() === \"user-query\";\n          var body = user ? el.querySelector(\".query-text\") || el : el.querySelector(\"message-content\") || el;\n          out.push({ role: user ? \"user\" : \"assistant\", text: textOf(body) });\n        });\n        return out;\n      },\n      busy: function (doc) {\n        return !!doc.querySelector('button[aria-label*=\"Stop\"], .stop-icon');\n      }\n    }\n  };\n\n  var sel = SELECTORS[site];\n  var tracker = null;\n  var trackerFor = null;\n  var backfill = false;\n  var timer = null;\n\n  function schedule(ms) {\n    if (timer === null) timer = setTimeout(scan, ms);\n  }\n\n  function scan() {\n    timer = null;\n    var conversation = core.conversationOf(site, location.pathname);\n    if (!conversation) {\n      tracker = null;\n      trackerFor = null;\n      return;\n    }\n    if (trackerFor !== conversation) {\n      tracker = core.createTracker({ backfill: backfill });\n      trackerFor = conversation;\n    }\n    var turns = core.withIds(conversation, sel.turns(document));\n    var ready = tracker.update(Date.now(), turns, sel.busy(document));\n    if (ready.length > 0) {\n      try {\n        chrome.runtime.sendMessage({ type: \"cortex-turns\", site: site, conversation: conversation, title: core.cleanTitle(document.title), turns: ready });\n      } catch (e) {\n        return; /* the extension was reloaded: this page's copy of the script stops */\n      }\n    }\n    if (tracker.pending()) schedule(1000);\n  }\n\n  chrome.storage.local.get({ backfill: false }, function (v) {\n    backfill = v.backfill === true;\n    new MutationObserver(function () { schedule(1000); }).observe(document.body, { childList: true, subtree: true, characterData: true });\n    setInterval(function () { if (trackerFor !== core.conversationOf(site, location.pathname)) schedule(0); }, 1500);\n    schedule(1000);\n  });\n})();\n",
  "background.js": "/*\n * Cortex live capture: the background script. It is the only part that talks to Cortex, and only to\n * http://127.0.0.1:<port> on this computer, with the token you pasted on the options page. It posts the finished\n * turns the page script hands it, keeps a short queue while Cortex is not running, and registers the page script\n * only for sites you approved (and granted the browser permission for).\n */\nimportScripts(\"core.js\");\n\nvar core = self.CortexCaptureCore;\nvar PENDING_MAX = 200;\n\nfunction getSettings() {\n  return chrome.storage.local.get({ port: 47831, token: \"\", sites: {}, backfill: false, pending: [], status: null });\n}\n\nfunction setStatus(ok, reason, sentMore) {\n  return chrome.storage.local.get({ status: null }).then(function (v) {\n    var prev = v.status || { sent: 0 };\n    return chrome.storage.local.set({ status: { at: new Date().toISOString(), ok: ok, reason: reason || \"\", sent: (prev.sent || 0) + (sentMore || 0) } });\n  });\n}\n\nfunction endpoint(port, path) {\n  return \"http://127.0.0.1:\" + Number(port) + path;\n}\n\n/* One request to Cortex. Resolves { ok, reason, retry }. */\nfunction call(s, method, path, body) {\n  return fetch(endpoint(s.port, path), {\n    method: method,\n    headers: { Authorization: \"Bearer \" + s.token, \"Content-Type\": \"application/json\" },\n    body: body === undefined ? undefined : JSON.stringify(body)\n  }).then(\n    function (res) {\n      return res.json().catch(function () { return {}; }).then(function (j) {\n        if (res.ok) return { ok: true, reason: \"\", retry: false, body: j };\n        return { ok: false, reason: (j && j.reason) || \"refused\", retry: res.status >= 500 };\n      });\n    },\n    function () { return { ok: false, reason: \"unreachable\", retry: true }; }\n  );\n}\n\nvar flushing = false;\n\n/* Post what is waiting, oldest first; stops at the first post Cortex could not be reached for (it stays queued). */\nasync function flush() {\n  if (flushing) return;\n  flushing = true;\n  try {\n    var s = await getSettings();\n    if (!s.token || s.pending.length === 0) return;\n    var left = s.pending.slice();\n    var sent = 0;\n    while (left.length > 0) {\n      var r = await call(s, \"POST\", \"/v1/turns\", left[0]);\n      if (r.ok) {\n        sent += left[0].turns.length;\n        left.shift();\n      } else if (r.retry) {\n        await setStatus(false, r.reason, 0);\n        break;\n      } else {\n        /* refused (paused, site not approved, wrong token): a refused post is not kept */\n        await setStatus(false, r.reason, 0);\n        left.shift();\n      }\n    }\n    await chrome.storage.local.set({ pending: left });\n    if (sent > 0) await setStatus(true, \"\", sent);\n  } finally {\n    flushing = false;\n  }\n}\n\nfunction enqueue(post) {\n  return getSettings().then(function (s) {\n    var pending = s.pending.concat([post]).slice(-PENDING_MAX);\n    return chrome.storage.local.set({ pending: pending });\n  }).then(flush);\n}\n\nfunction syncScripts() {\n  return getSettings().then(function (s) {\n    return chrome.scripting.getRegisteredContentScripts().then(function (have) {\n      var ids = {};\n      have.forEach(function (h) { ids[h.id] = true; });\n      var work = Object.keys(core.SITES).map(function (id) {\n        var site = core.SITES[id];\n        var rid = \"cortex-\" + id;\n        return chrome.permissions.contains({ origins: site.matches }).then(function (granted) {\n          var wanted = s.sites[id] === true && granted;\n          if (wanted && !ids[rid]) return chrome.scripting.registerContentScripts([{ id: rid, matches: site.matches, js: [\"core.js\", \"content.js\"], runAt: \"document_idle\", persistAcrossSessions: true }]);\n          if (!wanted && ids[rid]) return chrome.scripting.unregisterContentScripts({ ids: [rid] });\n        });\n      });\n      return Promise.all(work);\n    });\n  });\n}\n\nchrome.runtime.onMessage.addListener(function (msg, sender, reply) {\n  if (!msg || sender.id !== chrome.runtime.id) return false;\n  if (msg.type === \"cortex-turns\") {\n    var host = \"\";\n    try { host = new URL(sender.tab && sender.tab.url).hostname; } catch (e) { return false; }\n    var site = core.siteOfHost(host);\n    getSettings().then(function (s) {\n      if (!site || site !== msg.site || s.sites[site] !== true) return;\n      return enqueue({ v: 1, site: site, conversation: String(msg.conversation || \"\"), title: msg.title || undefined, turns: Array.isArray(msg.turns) ? msg.turns : [] });\n    });\n    return false;\n  }\n  if (msg.type === \"cortex-ping\") {\n    getSettings().then(function (s) {\n      if (!s.token) return { ok: false, reason: \"no-token\" };\n      return call(s, \"GET\", \"/v1/ping\");\n    }).then(reply);\n    return true;\n  }\n  if (msg.type === \"cortex-sync\") {\n    syncScripts().then(function () { reply({ ok: true }); }, function () { reply({ ok: false }); });\n    return true;\n  }\n  return false;\n});\n\nchrome.runtime.onInstalled.addListener(function () { syncScripts(); });\nchrome.runtime.onStartup.addListener(function () { syncScripts(); flush(); });\nchrome.alarms.create(\"cortex-flush\", { periodInMinutes: 1 });\nchrome.alarms.onAlarm.addListener(function (a) { if (a.name === \"cortex-flush\") flush(); });\n",
  "options.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Cortex live capture</title>\n<style>\n  :root { color-scheme: light dark; font-family: system-ui, sans-serif; }\n  body { max-width: 34rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.45; }\n  h1 { font-size: 1.25rem; }\n  fieldset { border: 1px solid #8884; border-radius: 8px; margin: 1rem 0; padding: .75rem 1rem; }\n  legend { padding: 0 .4rem; font-weight: 600; }\n  label { display: block; margin: .4rem 0; }\n  input[type=text], input[type=password], input[type=number] { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }\n  button { font: inherit; padding: .4rem .9rem; }\n  .note { opacity: .75; font-size: .9rem; }\n  #status { margin-top: .75rem; }\n</style>\n</head>\n<body>\n<h1>Cortex live capture</h1>\n<p class=\"note\">Sends each finished chat turn on the sites you tick to Cortex, running on this computer (127.0.0.1). It sends nothing anywhere else.</p>\n\n<fieldset>\n  <legend>Connection</legend>\n  <label>Port <input id=\"port\" type=\"number\" min=\"1024\" max=\"65535\" value=\"47831\"></label>\n  <label>Token (copy it from Cortex, Sources, Live capture) <input id=\"token\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\"></label>\n  <button id=\"test\" type=\"button\">Test the connection</button>\n  <div id=\"status\" class=\"note\" role=\"status\"></div>\n</fieldset>\n\n<fieldset>\n  <legend>Sites this add-on may read</legend>\n  <label><input type=\"checkbox\" data-site=\"chatgpt\"> ChatGPT (chatgpt.com, chat.openai.com)</label>\n  <label><input type=\"checkbox\" data-site=\"claude\"> Claude (claude.ai)</label>\n  <label><input type=\"checkbox\" data-site=\"gemini\"> Gemini (gemini.google.com)</label>\n  <p class=\"note\">Unticking a site removes the browser permission, and the add-on can no longer read that site. Cortex also keeps its own list: a site must be approved there too.</p>\n</fieldset>\n\n<fieldset>\n  <legend>Older messages</legend>\n  <label><input id=\"backfill\" type=\"checkbox\"> Also send the messages already on screen when I open a conversation</label>\n  <p class=\"note\">Off by default: only turns that finish while the page is open are sent.</p>\n</fieldset>\n\n<script src=\"core.js\"></script>\n<script src=\"options.js\"></script>\n</body>\n</html>\n",
  "options.js": "/* Cortex live capture: the options page. Settings live in this browser only (chrome.storage.local). */\n(function () {\n  \"use strict\";\n  var core = globalThis.CortexCaptureCore;\n  var $ = function (id) { return document.getElementById(id); };\n  var REASONS = {\n    unreachable: \"Cortex did not answer. Is it open, and is live capture turned on in Sources?\",\n    \"no-token\": \"Paste the token first.\",\n    \"bad-token\": \"Cortex does not accept this token. Copy it again from Sources, Live capture.\",\n    paused: \"Cortex has capture paused.\",\n    \"site-off\": \"That site is not approved in Cortex yet.\",\n    \"bad-host\": \"The port does not look like Cortex's.\",\n    \"bad-origin\": \"Cortex refused this add-on.\",\n    \"rate-limited\": \"Too many wrong tokens just now; wait a minute.\"\n  };\n\n  function show(text) { $(\"status\").textContent = text; }\n\n  function load() {\n    chrome.storage.local.get({ port: 47831, token: \"\", sites: {}, backfill: false, status: null }).then(function (s) {\n      $(\"port\").value = s.port;\n      $(\"token\").value = s.token;\n      $(\"backfill\").checked = s.backfill === true;\n      document.querySelectorAll(\"[data-site]\").forEach(function (box) {\n        var id = box.getAttribute(\"data-site\");\n        chrome.permissions.contains({ origins: core.SITES[id].matches }).then(function (granted) { box.checked = s.sites[id] === true && granted; });\n      });\n      if (s.status) show((s.status.ok ? \"Last post worked. \" : \"Last post was refused: \" + (REASONS[s.status.reason] || s.status.reason) + \" \") + \"Turns sent so far: \" + (s.status.sent || 0) + \".\");\n    });\n  }\n\n  function save() {\n    var port = Number($(\"port\").value);\n    chrome.storage.local.set({ port: Number.isInteger(port) && port >= 1024 && port <= 65535 ? port : 47831, token: $(\"token\").value.trim(), backfill: $(\"backfill\").checked });\n  }\n\n  [\"port\", \"token\", \"backfill\"].forEach(function (id) { $(id).addEventListener(\"change\", save); });\n\n  $(\"test\").addEventListener(\"click\", function () {\n    save();\n    show(\"Asking Cortex…\");\n    chrome.runtime.sendMessage({ type: \"cortex-ping\" }, function (r) {\n      show(r && r.ok ? \"Connected. Cortex answered.\" : REASONS[(r && r.reason) || \"unreachable\"] || \"Cortex refused: \" + (r && r.reason));\n    });\n  });\n\n  document.querySelectorAll(\"[data-site]\").forEach(function (box) {\n    box.addEventListener(\"change\", function () {\n      var id = box.getAttribute(\"data-site\");\n      var origins = core.SITES[id].matches;\n      var apply = function (on) {\n        chrome.storage.local.get({ sites: {} }).then(function (s) {\n          s.sites[id] = on;\n          return chrome.storage.local.set({ sites: s.sites });\n        }).then(function () { chrome.runtime.sendMessage({ type: \"cortex-sync\" }); });\n      };\n      if (box.checked) {\n        chrome.permissions.request({ origins: origins }).then(function (ok) { box.checked = ok; apply(ok); });\n      } else {\n        apply(false);\n        chrome.permissions.remove({ origins: origins }).then(function () { chrome.runtime.sendMessage({ type: \"cortex-sync\" }); });\n      }\n    });\n  });\n\n  load();\n})();\n",
  "README.md": "# Cortex live capture (browser add-on)\n\nA small Manifest V3 add-on for Chrome, Edge and Brave that sends each finished chat turn on the sites you approve to\nCortex, which must be running on the same computer. It talks to `http://127.0.0.1:<port>` only.\n\n## Install by hand\n\n1. In Cortex, open Sources, Live capture, read what is stored, and turn it on. Use \"Save the add-on\" and unzip it\n   (or use this folder as it is).\n2. In the browser open `chrome://extensions` (or `edge://extensions`), switch on Developer mode, choose\n   \"Load unpacked\" and pick the folder.\n3. Open the add-on's options page. Paste the token from Cortex (Sources, Live capture, Copy token), keep the port in\n   step with Cortex, and tick the sites you want. The browser asks for each site's permission; unticking removes it.\n4. \"Test the connection\" should answer \"Connected\".\n\n## What it does and does not do\n\n- It reads the chat messages on the ticked sites only, waits until a reply has finished, and posts the turn\n  (id, who said it, the text) to Cortex. Older messages already on screen are not sent unless you tick that option.\n- Cortex refuses any post without the token, from anything but this computer, or for a site you have not approved\n  there. Cortex counts what it refuses.\n- Nothing is sent to any server. The token and options stay in this browser's local extension storage.\n- The selectors that find messages live in `content.js` and can go out of date when a site changes its page.\n\n## Files\n\n`manifest.json`, `core.js` (which turns are finished), `content.js` (reads the page), `background.js` (posts to\nCortex), `options.html` and `options.js`. The same files are embedded in Cortex (`src/shared/captureAddon.ts`,\nproduced by `node scripts/embed-addon.mjs`); a test fails when the two differ.\n"
};
